btn" onclick="openFriendLeague(<?=$selectedLeagueId?>)">League details</button><button type="button" class="copybtn" data-name="<?=htmlspecialchars($selectedLeague['name'],ENT_QUOTES)?>" data-code="<?=htmlspecialchars($selectedLeague['code'],ENT_QUOTES)?>" onclick="shareLeague(this.dataset.name,this.dataset.code)">Invite friends</button><a class="copybtn" href="/league/<?=rawurlencode($selectedLeague['code'])?>">League page</a></div><?php endif;?></div><div class="side"><?php if($friendProgress)echo leaguePersonalHtml($friendProgress);$n=$leaderOffset+1;foreach($leaders as $l):?><div <?=((int)$l['id']===$uid)?'id="my-league-position" style="scroll-margin-top:100px"':''?> class="row <?=($friendProgress?!empty($l['is_you']):(int)$l['id']===$uid)?'leagueyou':''?>"><b><?=$friendProgress?$l['rank']:$n++?></b><span><button type="button" class="playerlink" onclick="openPlayerResults(<?=(int)$l['id']?>)"><?=htmlspecialchars($l['display_name'])?></button><?php if(!empty($l['is_bot'])):?><small class="simbadge">SIM<?=max(1,min(5,(int)($l['bot_grade']??5)))?></small><?php endif;?><?php if(!$friendProgress&&empty($l['listed'])):?><small class="provisional" title="Only you can see this row until you have played two matchweeks or added an email">Only you</small><?php endif;?><?php if($friendProgress):?><small class="leaguegap"><?=leagueMovementHtml($l['movement'])?> · <?=$l['round_pts']?> this week<?=$l['gap']?' · '.$l['gap'].' pts to next':''?></small><?php endif;?></span><b><?=$l['pts']?></b></div><?php endforeach;?></div><?php if($leaderPages>1):?><nav class="tablepager" aria-label="Leaderboard pages"><a class="<?=$leaderPage<=1?'disabled':''?>" <?=$leaderPage>1?'href="?table='.urlencode($leaderPeriod).$leaderScopeQuery.'&page='.($leaderPage-1).'#leader"':'aria-disabled="true"'?>>Previous</a><span>Page <?=$leaderPage?> of <?=$leaderPages?></span><a class="<?=$leaderPage>=$leaderPages?'disabled':''?>" <?=$leaderPage<$leaderPages?'href="?table='.urlencode($leaderPeriod).$leaderScopeQuery.'&page='.($leaderPage+1).'#leader"':'aria-disabled="true"'?>>Next</a></nav><?php endif;?></section><div class="promo"><b>Scoring</b><p>5 points exact score · 3 points correct result · 0 otherwise. For example, predict 2–1: a 2–1 result earns 5 points; a 1–0 result earns 3. <a href="/how-it-works">Full scoring guide</a>.</p></div></aside><dialog id="scorePickerDialog" aria-labelledby="scorePickerTitle"><div class="profilemodal scorepickermodal"><button type="button" class="closex" onclick="closeScorePicker()" aria-label="Close score picker">×</button><div class="sectionlabel" id="scorePickerPosition">YOUR PREDICTION</div><h2 id="scorePickerTitle">Choose the score</h2><div class="pickerteams"><div class="pickerteam"><img id="pickerHomeLogo" alt=""><strong id="pickerHomeName"></strong><button type="button" data-side="home" data-delta="1" onclick="adjustPicker('home',1)" aria-label="Increase home score">+</button><output id="pickerHomeScore">0</output><button type="button" data-side="home" data-delta="-1" onclick="adjustPicker('home',-1)" aria-label="Decrease home score">−</button></div><div class="pickerv">v</div><div class="pickerteam"><img id="pickerAwayLogo" alt=""><strong id="pickerAwayName"></strong><button type="button" data-side="away" data-delta="1" onclick="adjustPicker('away',1)" aria-label="Increase away score">+</button><output id="pickerAwayScore">0</output><button type="button" data-side="away" data-delta="-1" onclick="adjustPicker('away',-1)" aria-label="Decrease away score">−</button></div></div><div id="pickerOdds" hidden aria-label="Match result odds"></div><p id="pickerStatus" class="pickerstatus" role="status">Use + and − to choose each score.</p><div class="pickernav"><button type="button" class="outline" id="pickerPrevious" onclick="commitPicker(-1)">Save &amp; previous</button><button type="button" class="btn" id="pickerNext" onclick="commitPicker(1)">Save &amp; next</button></div><button type="button" class="pickerDone" onclick="commitPicker(0)">Save &amp; close</button></div></dialog><dialog id="playerResultsDialog"><div class="profilemodal historymodal"><button type="button" class="closex" onclick="closePlayerResults()" aria-label="Close">×</button><div class="sectionlabel" id="playerResultsPeriod">PLAYER RESULTS</div><div class="botresulthead"><img id="playerResultsAvatar" alt="" hidden><div><h2 id="playerResultsName">Player predictions</h2><button type="button" class="botprofilelink" id="botProfileLink" onclick="openBotProfile()" hidden>Meet this bot</button></div></div><p class="explain">Predictions are shown once each match has kicked off.</p><div class="historylist" id="playerResultsList"><div class="emptyhistory">Loading predictions…</div></div></div></dialog><dialog id="botProfileDialog"><div class="profilemodal botprofilecard"><button type="button" class="closex" onclick="closeBotProfile()" aria-label="Close">×</button><div class="sectionlabel">BOT PROFILE</div><img class="botlarge" id="botProfileAvatar" alt=""><h2 id="botProfileName">Bot</h2><div class="botprofiletitle" id="botProfileTitle"></div><p class="botbio" id="botProfileBio"></p><p class="botgradekey" id="botProfileGrade"></p></div></dialog><dialog id="historyDialog"><div class="profilemodal historymodal"><button type="button" class="closex" onclick="closeHistory()" aria-label="Close">×</button><div class="sectionlabel">YOUR RESULTS</div><h2>My Results</h2><div class="resulttabs" role="tablist" aria-label="Your results view"><button type="button" id="performanceTab" role="tab" aria-controls="performancePanel" aria-selected="false" onclick="showResultsTab('performance')">Performance</button><button type="button" id="matchesTab" role="tab" aria-controls="matchesPanel" aria-selected="true" onclick="showResultsTab('matches')">Match history</button></div><section id="performancePanel" class="performancebody" role="tabpanel" aria-labelledby="performanceTab" hidden><?php if($performance):renderPersonalPerformance($performance);else:?><p class="emptyhistory">Sign in to see your performance.</p><?php endif;?></section><div class="historylist" id="matchesPanel" role="tabpanel" aria-labelledby="matchesTab"><?php if(!$predictionHistory):?><div class="emptyhistory">Your first points will appear here after your predicted matches finish. <a href="/#predict">Make your next prediction →</a></div><?php endif;?><?php $lastHistoryGroup=null;foreach($predictionHistory as $h):$roundLabel=trim((string)($h['round']??''));$hasRound=preg_match('/(?:round|regular season|matchweek|gameweek)\s*[-·:]?\s*\d+/i',$roundLabel);$groupDate=(new DateTimeImmutable($h['kickoff_utc'],new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Europe/London'));$groupDate=$groupDate->modify('-'.(((int)$groupDate->format('w')+2)%7).' days');$groupKey=$hasRound?$roundLabel:$groupDate->format('Y-m-d');$groupLabel=$hasRound?$roundLabel:'Games · week of '.$groupDate->format('d M Y');if($groupKey!==$lastHistoryGroup):$lastHistoryGroup=$groupKey;?><div class="historyround"><?=htmlspecialchars($groupLabel)?></div><?php endif;$finished=$h['actual_home']!==null&&$h['actual_away']!==null;?><article class="historyrow <?=$finished&&$h['points']==5?'historyexact':($finished&&$h['points']==3?'historycorrect':'')?>"><time><?=gmdate('D d M Y, H:i',strtotime($h['kickoff_utc']))?></time><div class="historymatch"><strong class="historyteam historyhome"><span class="historyname"><?=htmlspecialchars($h['home'])?></span><img src="/club-logo.php?team=<?=urlencode($h['home'])?>" alt="" width="22" height="22" loading="lazy"></strong><span>v</span><strong class="historyteam historyaway"><img src="/club-logo.php?team=<?=urlencode($h['away'])?>" alt="" width="22" height="22" loading="lazy"><span class="historyname"><?=htmlspecialchars($h['away'])?></span></strong></div><div class="historyscores"><span>Prediction <b><?=$h['predicted_home']?>–<?=$h['predicted_away']?></b></span><span>Result <b><?=$finished?$h['actual_home'].'–'.$h['actual_away']:'Pending'?></b></