l><div class="clubselect"><img id="selectedClubLogo" alt="" width="36" height="36" <?php if(!empty($user['supported_club'])):?>src="/club-logo.php?team=<?=urlencode($user['supported_club'])?>"<?php else:?>style="visibility:hidden"<?php endif;?>><select id="supportedClub"><option value="">None</option><?php foreach($premierLeagueClubs as $club):?><option value="<?=htmlspecialchars($club)?>" <?=($user['supported_club']??'')===$club?'selected':''?>><?=htmlspecialchars($club)?></option><?php endforeach;?></select></div></label><section class="reminderprefs"><h3>Prediction reminders</h3><?php $remindState=pc_reminder_state($user);?><?php if(in_array($remindState,['ready','unverified'],true)):?><label class="remindercheck"><input type="checkbox" id="predictionReminders" <?=!empty($user['prediction_reminders'])?'checked':''?>>Email me when I have missing picks</label><label class="remindertiming">Remind me<select id="reminderLead"><option value="24" <?=($user['reminder_lead_hours']??24)==24?'selected':''?>>About 24 hours before kick-off</option><option value="2" <?=($user['reminder_lead_hours']??24)==2?'selected':''?>>About 2 hours before kick-off</option></select></label><p>Sent to <?=htmlspecialchars((string)$user['email'])?>. At most one email per matchweek, only if picks are missing. Switch off here or through the email.<?=$remindState==='unverified'?' We’ll first email you a link to confirm this address.':''?></p><?php else:?><input type="checkbox" id="predictionReminders" hidden><p>Save your account with an email to get a reminder before your picks lock.</p><?php endif;?></section><button class="btn profilesave" type="submit">Save changes</button><p id="profileSaveStatus" class="authmessage" role="status" aria-live="polite"></p></form></dialog><?php if($uid>0&&empty($user['onboarding_seen'])):?><dialog id="welcomeDialog" aria-labelledby="welcomeTitle"><div class="profilemodal welcomemodal"><div class="sectionlabel">WELCOME TO PREDICTIONCOMP</div><h2 id="welcomeTitle">Your first predictions</h2><ol class="welcomesteps"><li><b>Choose each score</b><p>Use Edit score on mobile, or the score fields on desktop. A 0–0 prediction is valid.</p></li><li><b>Check it is saved</b><p>Save &amp; next or Save &amp; close confirms a mobile pick. Desktop changes save automatically. Look for Saved; To pick means you still have a pick to make.</p></li><li><b>Beat the deadline</b><p>You can change a saved pick until kick-off. After that it is Locked.</p></li><li><b>Earn points</b><p>5 points for an exact score, 3 for the correct result, otherwise 0. Follow your progress in My Results and Leagues.</p></li></ol><button type="button" class="btn" onclick="finishWelcome(this)">Start predicting</button><p id="welcomeStatus" role="status" class="authmessage"></p></div></dialog><?php endif;?></main><footer class="footer"><nav class="footerlinks" aria-label="Site information"><a href="/clubs">Clubs</a><a href="/fixtures">Fixtures</a><a href="/table">PL Table</a><a href="/about">About</a><a href="/how-it-works">How it works</a><a href="/privacy">Privacy Policy</a><a href="/contact">Contact</a></nav><span>PredictionComp.com · Independent prediction game · Not affiliated with or endorsed by the Premier League or any club</span><p class="sistersite" style="margin:10px 0 0;font-size:12px;line-height:1.6;color:inherit">More football fun: <a href="https://clubdailyfive.com/" style="color:inherit;text-decoration:underline;text-underline-offset:3px">ClubDailyFive</a> · daily club quizzes &amp; Player Wordle</p></footer><div class="infomodal" id="infoModal" hidden aria-hidden="true"><article class="infodialog" role="dialog" aria-modal="true" aria-labelledby="infoTitle"><button class="infoclose" id="infoClose" type="button" aria-label="Close">×</button><div id="infoContent"></div></article></div><?php playerNavigation(true);?><script>window.PC=<?=json_encode(['csrf'=>$_SESSION['registration_csrf'],'afterSignIn'=>$afterSignIn,'leagueShare'=>PC_LEAGUE_SHARE_TEMPLATE,'inviteBase'=>PC_LEAGUE_INVITE_BASE,'signedIn'=>$uid>0,'leaderPeriod'=>$leaderPeriod,'matchweek'=>$matchweek,'predIds'=>array_map('intval',array_keys($pred)),'predCount'=>count($pred),'nameWords'=>PC_NAME_WORDS,'myLeagues'=>array_map(fn($l)=>['id'=>(int)$l['id'],'name'=>$l['name'],'code'=>$l['code']],$myLeagues),'pendingInviteCode'=>$pendingInviteName?(string)$_SESSION['pending_league_code']:null],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?></script><script src="/assets/share.js?v=1"></script><script src="/assets/home.js?v=5"></script><?php if($uid<1):?><dialog id="guestNameDialog" aria-labelledby="guestNameTitle"><form class="guestname" onsubmit="confirmGuestName(event)"><button type="button" class="closex" onclick="document.getElementById('guestNameDialog').close()" aria-label="Close">×</button><p class="dialogkicker">One last step</p><h2 id="guestNameTitle">Pick your name for the table</h2><p class="explain">This is how other players will see you. Keep our suggestion or type your own. You can change it later in Account.</p><label for="guestNameInput">Display name</label><div class="guestnamefield"><input id="guestNameInput" minlength="2" maxlength="24" autocomplete="nickname" required value="<?=htmlspecialchars(pc_suggest_name($db))?>" oninput="updateGuestButton()"><button type="button" class="ghost" onclick="shuffleGuestName()">Shuffle</button></div><input class="hp" id="guestNameWebsite" tabindex="-1" autocomplete="off" aria-hidden="true"><p class="authmessage" id="guestNameMessage" role="status"></p><button type="submit" class="btn wide" id="guestNameSubmit">Play as this name</button><p class="guestnote">Your picks are kept in this browser. You’ll join the global table after your second matchweek. <button type="button" class="textbtn" onclick="guestToRegister()">Register with email or Google</button> to play on any device.</p></form></dialog><script src="/assets/home-guest.js?v=1"></script><?php endif;?><?php if(!empty($leaderFocusMe)):?><script>
window.addEventListener('load',function(){
 const row=document.getElementById('my-league-position'),table=document.getElementById('leader');
 if(!row||!table)return;
 const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 if(reduced){row.scrollIntoView({block:'center',behavior:'instant'});return;}
 table.scrollIntoView({block:'start',behavior:'instant'});
 let cancelled=false;
 const cancel=()=>{cancelled=true;};
 ['wheel','touchstart','pointerdown','keydown'].forEach(type=>window.addEventListener(type,cancel,{once:true,passive:true}));
 setTimeout(function(){if(!cancelled)row.scrollIntoView({block:'center',behavior:'smooth'});},300);
},{once:true});
</script><?php endif;?><script>
if(location.hash==='#prediction-matchweek'){
 const showWeek=()=>requestAnimationFrame(()=>document.getElementById('prediction-matchweek')?.scrollIntoView({block:'start',behavior:'instant'}));
 window.addEventListener('load',showWeek,{once:true});
 window.addEventListener('pageshow',showWeek);
}
</script></body></html>
